@Component
public class OrderSagaOrchestrator {
    private final OrderServiceClient orderClient;
    private final PaymentServiceClient paymentClient;
    private final InventoryServiceClient inventoryClient;

    public void executeSaga(OrderCreateDto dto) {
        String sagaId = UUID.randomUUID().toString();
        try {
            var order = orderClient.createPendingOrder(dto, sagaId);
            paymentClient.processPayment(order.getId(), order.getAmount(), sagaId);
            inventoryClient.reserveStock(order.getItems(), sagaId);
            orderClient.completeOrder(order.getId(), sagaId);
        } catch (PaymentFailedException | InventoryOutOfStockException e) {
            rollbackSaga(sagaId, dto);
        }
    }

    private void rollbackSaga(String sagaId, OrderCreateDto dto) {
        inventoryClient.releaseStockCompensate(dto, sagaId);
        paymentClient.refundCompensate(sagaId);
        orderClient.cancelOrderCompensate(sagaId);
    }
}
